+		ret = mas_empty_area(mas, range_lo, range_hi, 1);
+		if ((mas->tree->ma_flags & MT_FLAGS_ALLOC_WRAPPED) && ret == 0) {
+			mas->tree->ma_flags &= ~MT_FLAGS_ALLOC_WRAPPED;
 			ret = 1;
-	}
-	if (ret < 0)
-		return ret;
+		}
+		if (ret < 0 && range_lo > min) {
+			mas_reset(mas);
+			ret = mas_empty_area(mas, min, range_hi, 1);
